@pytest.mark.parametrize("shape", ["triangle", "cycle"]) @pytest.mark.parametrize("gpu_device", [0, 1]) @pytest.mark.parametrize( ("operation", "backend", "parameters", "field", "expected"), [("triangle-counting", b, {}, "count", 1) for b in ("tot", "wetric")] + [("maximal-cliques", b, {}, "count", 2) for b in ("rdmce", "mce-gpu", "g2-aimd")] + [ ("maximum-clique", b, {}, "maximum_size", 3) for b in ("cuda-ms", "gpu-maximum-clique", "maximum-clique-on-gpu") ] + [("k-cliques", b, {"k": 3}, "count", 1) for b in ("graphset", "gamma", "kcgpu")] + [ ("k-core", b, {}, "core_numbers", [2, 2, 2, 0]) for b in ("kcore-gpu", "libcugraph") ], ) def test_original_cuda_backends_keep_cli_json_and_restore_device( operation, backend, parameters, field, expected, gpu_device, shape ): lib = library(ORIGINAL) runtime = ctypes.CDLL(ctypes.util.find_library("cudart")) runtime.cudaGetDevice.argtypes = [ctypes.POINTER(ctypes.c_int)] runtime.cudaSetDevice.argtypes = [ctypes.c_int] before = ctypes.c_int() assert runtime.cudaSetDevice(1 - gpu_device) == 0 assert runtime.cudaGetDevice(ctypes.byref(before)) == 0 selected = gpu_device value = graph() value["graph"]["directed"] = False value["edges"].append({"id": 2, "source": 9007199254740993, "target": 0}) if shape == "cycle": value["vertices"] = [{"id": i} for i in range(5)] value["edges"] = [ {"id": i, "source": i, "target": (i + 1) % 5} for i in range(5) ] expected = { "triangle-counting": 0, "maximal-cliques": 5, "maximum-clique": 2, "k-cliques": 0, "k-core": [2] * 5, }[operation] result = lib.run( operation, value, parameters=parameters, device="gpu", backend=backend, gpu_device=selected, ) after = ctypes.c_int() assert runtime.cudaGetDevice(ctypes.byref(after)) == 0 assert after.value == before.value actual = ( [row["core_number"] for row in result["result"]["vertices"]] if field == "core_numbers" else result["result"][field] ) assert actual == expected assert result["backend"]["hardware"]["device_ordinal"] == selected request = { "command": "run", "operation": operation, "parameters": parameters, "graph": value, "device": "gpu", "backend": backend, "gpu_device": selected, } process = subprocess.run( [ORIGINAL / "graphmine-native", "request"], input=json.dumps(request), capture_output=True, text=True, check=True, ) # This must parse the entire stdout: upstream timing diagnostics previously # corrupted it even though the C++ count itself was correct. cli = json.loads(process.stdout) assert cli["backend"]["id"] == backend > assert without_timing(cli) == without_timing(result) E AssertionError: assert {'backend': {... 'cores', ...} == {'backend': {... 'cores', ...} E E Omitting 15 identical items, use -vv to show E Differing items: E {'implementation_sha256': '97123f2f9b01022f5d87ba7bd285da1fb7b2dc7a85b9b680e3d995dc02a03206'} != {'implementation_sha256': '12a33e64eebb459f619788a145dc232fefc6852d6b78048095ba22c7cb260baa'} E Use -v to get more diff
